        public static void SetCommandBlockMode(this IGlobalOptions options, int value) => options.SetOptionInt(LogicOptionItemID.commandBlockMode, value);
        public static void CycleCommandBlockMode(this IGlobalOptions options)
        {
            var mode = options.GetCommandBlockMode();
            mode = (mode + 1) % CommandBlockModes.COUNT;
            options.SetCommandBlockMode(mode);
        }
