        public static void SetHPBarHoverDisplayRange(this IGlobalOptions options, float value) => options.SetOptionFloat(LogicOptionItemID.hpBarHoverDisplayRange, value);

        public static int GetHPBarAmountMode(this IGlobalOptions options) => options.GetOptionInt(LogicOptionItemID.hpBarAmountMode);
        public static void SetHPBarAmountMode(this IGlobalOptions options, int value) => options.SetOptionInt(LogicOptionItemID.hpBarAmountMode, value);
