        public static float GetMusicVolume(this IGlobalOptions options) => options.GetOptionFloat(LogicOptionItemID.musicVolume);
        public static void SetMusicVolume(this IGlobalOptions options, float value) => options.SetOptionFloat(LogicOptionItemID.musicVolume, value);
